{
  "outcome": "patch",
  "candidate_reviews": {
    "C001": {
      "decision": "edit",
      "reason": "Required reference: encoding must use speedKph with mps converted to kph via *3.6 before encoding. TypeScript bindings use camelCase speedKph for the renamed field."
    },
    "C002": {
      "decision": "edit",
      "reason": "Required reference: observation key becomes speed_kph and field name is speedKph; value must be decoded float32 exposed as JSON number. Need to convert entity speedKph from kph to display."
    },
    "C003": {
      "decision": "edit",
      "reason": "Required reference: threshold changes to >108.0 kph (was >30.0 mps); uses entity.speedKph field. Need to update constant and field reference."
    }
  },
  "edits": [
    {
      "before": "    const sample = VehicleTelemetry.encode({ vehicleId: request.vehicle_id, speedMps: request.speed }).finish();\n",
      "after": "    const sample = VehicleTelemetry.encode({ vehicleId: request.vehicle_id, speedKph: request.speed * 3.6 }).finish();\n"
    },
    {
      "before": "    const fields = { vehicle_id: entity.vehicleId, speed_mps: entity.speedMps };\n",
      "after": "    const fields = { vehicle_id: entity.vehicleId, speed_kph: entity.speedKph };\n"
    },
    {
      "before": "    return { fields, speeding: entity.speedMps > 30.0, constructed_payload: Buffer.from(sample).toString(\"base64\") };\n",
      "after": "    return { fields, speeding: entity.speedKph > 108.0, constructed_payload: Buffer.from(sample).toString(\"base64\") };\n"
    }
  ],
  "rationale": "Schema rename from speed_mps to speed_kph with unit conversion at encoding time (mps * 3.6 = kph). Threshold for speeding changes from 30.0 mps to 108.0 kph (same physical speed). Observation key changes from speed_mps to speed_kph. The TypeScript bindings generate speedKph for the protobuf field speed_kph. All three candidates are required references that must be edited to maintain correct behavior through the full request->encode->decode->observe path.",
  "confidence": 0.95,
  "assumptions": [
    "TypeScript protobuf bindings use camelCase speedKph matching protobuf snake_case speed_kph",
    "Float32 precision is handled by protobuf library; we expose the decoded value directly",
    "Entity fields use the same naming convention as generated bindings (speedKph not speedMps)",
    "No mixed unit/version handling needed; coordinated rollout only"
  ]
}
